begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('f2600000-0000-4000-8000-000000000001','oauth-owner@example.test',now()),
 ('f2600000-0000-4000-8000-000000000002','oauth-staff@example.test',now()),
 ('f2600000-0000-4000-8000-000000000003','oauth-worker@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f2600000-0000-4000-8000-000000000001","role":"authenticated"}';
select set_config('test.tenant',create_tenant('OAuth test','paypal-oauth-test',gen_random_uuid())::text,true);
select set_config('test.cipher','{"iv":"aWl2","tag":"dGFn","data":"ZGF0YQ=="}',true);
select is(paypal_connection_status(current_setting('test.tenant')::uuid)->>'connected','false','new connection is absent');
select lives_ok($$select store_paypal_oauth(current_setting('test.tenant')::uuid,'f2600000-0000-4000-8000-000000000010',current_setting('test.cipher')::jsonb,now()+interval '1 hour',0)$$,'owner connects');
select throws_like($$select store_paypal_credentials(current_setting('test.tenant')::uuid,'f2600000-0000-4000-8000-000000000010',current_setting('test.cipher')::jsonb)$$,'%permission denied%','old write endpoint retired');
select is(paypal_connection_status(current_setting('test.tenant')::uuid)->>'connected','true','connected status');
select ok(not (paypal_connection_status(current_setting('test.tenant')::uuid) ? 'cipher'),'status never returns secrets');
select is(claim_paypal_refresh(current_setting('test.tenant')::uuid,1,gen_random_uuid())->>'status','valid','valid token is not refreshed');
select throws_like($$select store_paypal_oauth(current_setting('test.tenant')::uuid,'f2600000-0000-4000-8000-000000000011',current_setting('test.cipher')::jsonb,now()+interval '1 hour',1)$$,'%ZETTLE_WRONG_MERCHANT%','merchant cannot change');
select throws_like($$select store_paypal_oauth(current_setting('test.tenant')::uuid,'f2600000-0000-4000-8000-000000000010',current_setting('test.cipher')::jsonb,now()+interval '1 hour',0)$$,'%PAYPAL_CONNECTION_CHANGED%','stale callback refused');
reset role;
update paypal_credentials set expires_at=now()-interval '1 second' where tenant_id=current_setting('test.tenant')::uuid;
insert into tenant_members(tenant_id,user_id,role) values(current_setting('test.tenant')::uuid,'f2600000-0000-4000-8000-000000000002','staff');
set local role authenticated;
select set_config('test.claim',gen_random_uuid()::text,true);
select is(claim_paypal_refresh(current_setting('test.tenant')::uuid,1,current_setting('test.claim')::uuid)->>'status','claimed','one refresh claim');
select is(claim_paypal_refresh(current_setting('test.tenant')::uuid,1,gen_random_uuid())->>'status','busy','second refresh does not send old token');
select throws_like($$select finish_paypal_refresh(current_setting('test.tenant')::uuid,1,gen_random_uuid(),current_setting('test.cipher')::jsonb,now()+interval '1 hour')$$,'%PAYPAL_CONNECTION_CHANGED%','wrong claim refused');
select lives_ok($$select finish_paypal_refresh(current_setting('test.tenant')::uuid,1,current_setting('test.claim')::uuid,current_setting('test.cipher')::jsonb,now()+interval '1 hour')$$,'claim saves replacement');
select is(read_paypal_credentials(current_setting('test.tenant')::uuid)->>'revision','2','refresh increments revision');
select throws_like($$select finish_paypal_refresh(current_setting('test.tenant')::uuid,1,current_setting('test.claim')::uuid,current_setting('test.cipher')::jsonb,now()+interval '1 hour')$$,'%PAYPAL_CONNECTION_CHANGED%','refresh replay refused');
select throws_ok($$select * from paypal_credentials$$,'42501',null,'direct token read denied');
set local "request.jwt.claims"='{"sub":"f2600000-0000-4000-8000-000000000002","role":"authenticated"}';
select throws_ok($$select claim_paypal_refresh(current_setting('test.tenant')::uuid,2,gen_random_uuid())$$,'42501',null,'staff cannot refresh');
select throws_ok($$select paypal_connection_status(current_setting('test.tenant')::uuid)$$,'42501',null,'staff cannot manage connection');
select throws_ok($$select store_paypal_oauth(current_setting('test.tenant')::uuid,'f2600000-0000-4000-8000-000000000010',current_setting('test.cipher')::jsonb,now()+interval '1 hour',2)$$,'42501',null,'staff cannot connect');
select throws_ok($$select disconnect_paypal(current_setting('test.tenant')::uuid)$$,'42501',null,'staff cannot disconnect');
set local "request.jwt.claims"='{"sub":"f2600000-0000-4000-8000-000000000001","role":"authenticated"}';
select throws_ok($$select claim_paypal_refresh(gen_random_uuid(),1,gen_random_uuid())$$,'42501',null,'cross tenant refresh denied');
reset role;
update paypal_credentials set expires_at=now()-interval '1 second',refresh_claim=current_setting('test.claim')::uuid,refresh_started_at=now()-interval '2 minutes' where tenant_id=current_setting('test.tenant')::uuid;
set local role authenticated;
select is(claim_paypal_refresh(current_setting('test.tenant')::uuid,2,gen_random_uuid())->>'status','unknown','abandoned claim is not retried');
select is(paypal_connection_status(current_setting('test.tenant')::uuid)->>'reconnectRequired','true','unknown renewal requires reconnection');
select lives_ok($$select disconnect_paypal(current_setting('test.tenant')::uuid)$$,'owner disconnects');
select is(read_paypal_credentials(current_setting('test.tenant')::uuid),null,'disconnect removes usable tokens');
select is(paypal_connection_status(current_setting('test.tenant')::uuid)->>'merchantId','f2600000-0000-4000-8000-000000000010','disconnect retains merchant pin');
select throws_like($$select finish_paypal_refresh(current_setting('test.tenant')::uuid,2,current_setting('test.claim')::uuid,current_setting('test.cipher')::jsonb,now()+interval '1 hour')$$,'%PAYPAL_CONNECTION_CHANGED%','disconnect defeats in-flight refresh save');
select lives_ok($$select store_paypal_oauth(current_setting('test.tenant')::uuid,'f2600000-0000-4000-8000-000000000010',current_setting('test.cipher')::jsonb,now()+interval '1 hour',3)$$,'owner can reconnect the same merchant');
select enable_automation(current_setting('test.tenant')::uuid,gen_random_uuid(),'zettle_pull','oauth-worker@example.test');
set local "request.jwt.claims"='{"sub":"f2600000-0000-4000-8000-000000000003","role":"authenticated"}';
select throws_ok($$select claim_paypal_refresh(current_setting('test.tenant')::uuid,4,gen_random_uuid())$$,'42501',null,'unaccepted worker cannot refresh');
select accept_automation_grants();
select is(claim_paypal_refresh(current_setting('test.tenant')::uuid,4,gen_random_uuid())->>'status','valid','accepted scoped worker may renew');
select throws_ok($$select disconnect_paypal(current_setting('test.tenant')::uuid)$$,'42501',null,'worker cannot disconnect');
set local "request.jwt.claims"='{"sub":"f2600000-0000-4000-8000-000000000001","role":"authenticated"}';
select disable_automation(current_setting('test.tenant')::uuid,'zettle_pull');
set local "request.jwt.claims"='{"sub":"f2600000-0000-4000-8000-000000000003","role":"authenticated"}';
select throws_ok($$select claim_paypal_refresh(current_setting('test.tenant')::uuid,4,gen_random_uuid())$$,'42501',null,'revoked worker cannot renew');
reset role;
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),'f2600000-0000-4000-8000-000000000001','totp','verified',now(),now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f2600000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}';
select throws_like($$select paypal_connection_status(current_setting('test.tenant')::uuid)$$,'%AUTH_REQUIRED%','owner must satisfy MFA for status');
select throws_like($$select claim_paypal_refresh(current_setting('test.tenant')::uuid,4,gen_random_uuid())$$,'%AUTH_REQUIRED%','owner must satisfy MFA for refresh');
select throws_like($$select store_paypal_oauth(current_setting('test.tenant')::uuid,'f2600000-0000-4000-8000-000000000010',current_setting('test.cipher')::jsonb,now()+interval '1 hour',4)$$,'%AUTH_REQUIRED%','owner must satisfy MFA for connection');
select * from finish();
rollback;
